/// <summary>
/// Contract class for Rebate date table
/// </summary>
[DataContractAttribute]
public class METTAMRebateDateContract
{
    TAMRebateId tamRebateId;
    TAMRebateFromDate fromDate;
    TAMRebateToDate toDate;
    TAMRebateClaimBy tamRebateClaimBy;
    TAMRebateClaimPer tamRebateClaimPer;
    LineNum lineNum;
    TAMRebatePeriodCode tamRebatePeriodCode;
    TAMRebatePer tamRebatePer;
    TAMRebateProcessPosting tamRebateProcessPosting;
    TAMRebateStartingDayOfWeek tamRebateStartingDayOfWeek;

    const str agreementNumber = "agreementNumber";
    const str agreementValidFromDate = "agreementValidFromDate";
    const str agreementValidToDate = "agreementValidToDate";
    const str claimPeriodFrequency = "claimPeriodFrequency";
    const str claimPeriodRecurrence = "claimPeriodRecurrence";
    const str lineNumber = "lineNumber";
    const str provisionPeriodFrequency = "provisionPeriodFrequency";
    const str provisionPeriodRecurrence = "ProvisionPeriodRecurrence";
    const str willSourceDocumentPostingCalculateProvision = "willSourceDocumentPostingCalculateProvision";
    const str provisionWeekDayPeriodStart = "provisionWeekDayPeriodStart";


}

